"""Half-open integer interval utilities."""


def _clean(intervals):
    """Yield non-empty (start, end) tuples from the input."""
    for start, end in intervals:
        if start < end:
            yield (start, end)


def merge(intervals):
    """Merge overlapping and touching intervals; sorted list of tuples."""
    result = []
    for start, end in sorted(_clean(intervals)):
        if result and start <= result[-1][1]:
            last_start, last_end = result[-1]
            if end > last_end:
                result[-1] = (last_start, end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    gaps = []
    cur = ws
    for start, end in merge(intervals):
        if end <= cur:
            continue
        if start > cur:
            gaps.append((cur, start))
        if end >= we:
            return gaps
        cur = end
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Largest number of intervals covering one common point."""
    points = []
    for start, end in _clean(intervals):
        points.append((start, 1))
        points.append((end, -1))
    # Process ends before starts at the same coordinate (half-open ranges).
    points.sort(key=lambda p: (p[0], p[1]))
    depth = best = 0
    for _, delta in points:
        depth += delta
        if depth > best:
            best = depth
    return best

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._clock = clock
        # key -> (value, expiry_time or None)
        self._entries = OrderedDict()

    def _is_expired(self, expiry):
        return expiry is not None and self._clock() >= expiry

    def _purge_expired(self):
        """Remove all expired entries; return the number removed."""
        now = self._clock()
        expired = [
            k for k, (_, expiry) in self._entries.items()
            if expiry is not None and now >= expiry
        ]
        for k in expired:
            del self._entries[k]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self._clock()
        if key in self._entries:
            del self._entries[key]
        else:
            self._purge_expired()
            while len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        expiry = None if ttl is None else now + ttl
        self._entries[key] = (value, expiry)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        value, expiry = entry
        if self._is_expired(expiry):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return False
        return not self._is_expired(entry[1])

    def __len__(self):
        return len(self._entries)

    def keys(self):
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

